parameters.value:
{
  "username": "SOC · Wazuh SOAR",
  "embeds": [{
    "title": "Incidente de seguridad detectado",
    "color": 15158332,
    "description": "$clean.desc_safe",
    "fields": [
      {"name": "Resumen", "value": "$exec.description", "inline": false},
      {"name": "Origen (sensor)", "value": "$exec.source", "inline": true},
      {"name": "Severidad", "value": "$ioc.severity_final / 4", "inline": true},
      {"name": "Activo afectado", "value": "$ioc_python.agent", "inline": true},
      {"name": "Inteligencia de amenazas", "value": "$ioc.intel_summary", "inline": false},
      {"name": "Indicadores (IOCs)", "value": "$ioc_python.ioc_list", "inline": false},
      {"name": "Caso en TheHive", "value": "http://10.30.212.10:9000/cases/$case.body._id/details", "inline": false}
    ],
    "footer": {"text": "Generado automáticamente por Wazuh SOAR · Shuffle"}
  }]
}
